insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O trânsito de qualquer natureza nas vias terrestres abertas à circulação rege-se pelo Código. Trânsito é a utilização das vias por pessoas, veículos e animais, para circulação, parada, estacionamento e operação de carga ou descarga. O trânsito em condições seguras é direito de todos e dever dos órgãos do Sistema Nacional de Trânsito.', '["Aplica-se às vias terrestres abertas à circulação.","Conceito amplo de trânsito.","Trânsito seguro é direito de todos e dever dos órgãos do sistema."]'::jsonb, '["Trânsito inclui pessoas, veículos e animais.","Abrange parada, estacionamento e carga ou descarga."]'::jsonb, 'O pedestre que atravessa a rua também está no trânsito para fins do Código.', '["Assertiva que restringe o conceito de trânsito à circulação de veículos erra."]'::jsonb, '[{"termo":"Trânsito","significado":"Utilização das vias por pessoas, veículos e animais para circulação, parada, estacionamento e carga ou descarga."}]'::jsonb, '["Art. 2º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-1' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '366af6e513d03bd7f6314f49aaeab6af710de334434d2841a54b0bd8255f5d01'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'São vias terrestres urbanas e rurais as ruas, avenidas, logradouros, caminhos, passagens, estradas e rodovias, cujo uso é regulamentado pelo órgão com circunscrição sobre elas. Também são vias terrestres, para o Código, as praias abertas à circulação pública e as vias internas pertencentes a condomínios constituídos por unidades autônomas.', '["Rol de vias urbanas e rurais.","Regulamentação pelo órgão com circunscrição.","Praias abertas e vias de condomínios também contam."]'::jsonb, '["Praias abertas à circulação pública e vias de condomínio são vias terrestres para o Código."]'::jsonb, 'A rua interna de um condomínio de unidades autônomas está sujeita ao Código.', '["Assertiva que exclui as praias abertas à circulação pública do conceito de via terrestre erra."]'::jsonb, '[]'::jsonb, '["Art. 51"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-2' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '65314997aedda09f21365ccfc1d901b7c36209aa25aafcb602c477c72f840121'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As disposições do Código aplicam-se a qualquer veículo, bem como aos proprietários, aos condutores de veículos nacionais ou estrangeiros e às pessoas nele expressamente mencionadas.', '["Aplica-se a qualquer veículo.","Alcança proprietários e condutores, nacionais ou estrangeiros."]'::jsonb, '["Vale para veículos nacionais E estrangeiros."]'::jsonb, 'O turista estrangeiro que dirige no Brasil submete-se ao Código.', '["Assertiva que isenta condutores estrangeiros do Código erra."]'::jsonb, '[]'::jsonb, '["Art. 1º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-3' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '5e51ba937cdf4891ad7c41a99d1f02be6664a20f23e30aba8cda3b230a33009a'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

