insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Sistema Nacional de Trânsito é o conjunto de órgãos e entidades da União, dos Estados, do Distrito Federal e dos Municípios que tem por finalidade o exercício de atividades como planejamento, administração, normatização, pesquisa, registro e licenciamento de veículos, formação e habilitação de condutores, educação, engenharia, operação do sistema viário, policiamento, fiscalização, julgamento de infrações e recursos e aplicação de penalidades.', '["Conjunto de órgãos de todos os entes federativos.","Atividades de planejamento, normatização, registro, habilitação, fiscalização e julgamento."]'::jsonb, '["Sistema integrado por União, Estados, DF e Municípios."]'::jsonb, 'Detran, Contran e órgãos municipais integram o mesmo sistema.', '["Assertiva que restringe o sistema aos órgãos federais erra."]'::jsonb, '[]'::jsonb, '["Art. 7º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-5' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '90692d0526956ce54e82f85265ae93ddeaf2957867647e33765c0edea9d002ff'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'São objetivos básicos do Sistema Nacional de Trânsito estabelecer diretrizes da Política Nacional de Trânsito, voltadas à segurança, fluidez, conforto, defesa ambiental e educação para o trânsito; fixar a padronização de critérios técnicos, financeiros e administrativos; estabelecer a sistemática de fluxos permanentes de informações; e promover o aperfeiçoamento e o intercâmbio entre os órgãos.', '["Segurança, fluidez, conforto, defesa ambiental e educação.","Padronização de critérios.","Fluxo de informações e integração entre órgãos."]'::jsonb, '["Cinco valores da política: segurança, fluidez, conforto, defesa ambiental e educação."]'::jsonb, 'A padronização da sinalização em todo o país decorre desses objetivos.', '["Assertiva que exclui a defesa ambiental dos objetivos do sistema erra."]'::jsonb, '[]'::jsonb, '["Art. 5º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-6' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '53e47e4e01b302bf2ed9961e7d67e4c07e201704f220af820db4bc7d135cb3e8'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Compõem o Sistema Nacional de Trânsito o Contran, coordenador do Sistema e órgão máximo normativo e consultivo; os Conselhos Estaduais de Trânsito e o do Distrito Federal; os órgãos e entidades executivos de trânsito da União, dos Estados, do Distrito Federal e dos Municípios; os órgãos executivos rodoviários; a Polícia Rodoviária Federal; as Polícias Militares; as Juntas Administrativas de Recursos de Infrações; e as Câmaras Temáticas, entre outros.', '["Contran como órgão máximo normativo e consultivo.","Cetran e Contrandife.","Órgãos executivos de trânsito e rodoviários.","Polícia Rodoviária Federal, Polícias Militares e JARI."]'::jsonb, '["Contran é o órgão máximo NORMATIVO e consultivo.","ATUALIZAÇÃO: a composição do sistema foi alterada por leis posteriores; consulte o texto vigente."]'::jsonb, 'O Contran edita as resoluções que regulamentam o Código.', '["Assertiva que atribui ao Detran a função de órgão máximo normativo erra: é do Contran."]'::jsonb, '[{"termo":"Contran","significado":"Conselho Nacional de Trânsito, órgão máximo normativo e consultivo do sistema."}]'::jsonb, '["Art. 12"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-7' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '6915beb9d649ae95f55666ad34743aa4f6344b97b64cfddc4405f9d156a6ef4f'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A autoridade portuária ou a entidade concessionária de porto organizado pode celebrar convênios com os órgãos de trânsito, com a interveniência dos Municípios e Estados interessados, para facilitar a autuação por descumprimento da legislação de trânsito. O convênio vale para toda a área física do porto organizado.', '["Convênio entre autoridade portuária e órgãos de trânsito.","Finalidade: facilitar a autuação.","Vale para toda a área do porto organizado."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior.","Exige interveniência de Municípios e Estados."]'::jsonb, 'O porto firma convênio para que infrações em suas vias internas sejam autuadas.', '["Assertiva que dispensa convênio para a autuação em área portuária erra."]'::jsonb, '[]'::jsonb, '["Art. 7º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-7-a' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '7daf491148a1110cf3f25853189eefbed669e3c9b04d28bcbb4e0e58c1a8c578'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os Estados, o Distrito Federal e os Municípios organizam os respectivos órgãos e entidades executivos de trânsito e executivos rodoviários, estabelecendo os limites circunscricionais de suas atuações.', '["Cada ente organiza seus órgãos.","Definição dos limites de atuação."]'::jsonb, '["Circunscrição define quem tem competência sobre a via."]'::jsonb, 'O município cria seu órgão de trânsito e define a área de atuação.', '["Assertiva que atribui à União a organização dos órgãos municipais de trânsito erra."]'::jsonb, '[]'::jsonb, '["Art. 24"]'::jsonb, 'under_review', 'claude'
