insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Presidente da República designa o ministério ou órgão da Presidência responsável pela coordenação máxima do Sistema Nacional de Trânsito, ao qual fica vinculado o Contran e subordinado o órgão máximo executivo de trânsito da União.', '["Designação pelo Presidente da República.","Vinculação do Contran.","Subordinação do órgão máximo executivo da União."]'::jsonb, '["O órgão máximo executivo da União é subordinado; o Contran é vinculado."]'::jsonb, 'O decreto presidencial define a pasta que coordena o sistema.', '["Assertiva que atribui ao Contran a designação do ministério coordenador erra."]'::jsonb, '[]'::jsonb, '["Art. 10"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-9' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'e116512721dbb17b066c0c6fb04b3d2c594506e4965fe3fac22b76997a935752'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
