insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Contran tem sede no Distrito Federal e é composto por Ministros de Estado responsáveis por áreas definidas em lei, como ciência e tecnologia, educação, defesa, meio ambiente, saúde, justiça e relações exteriores, entre outras. Vários incisos foram revogados ou alterados por leis posteriores.', '["Sede no Distrito Federal.","Composto por Ministros de Estado.","Incisos alterados ou revogados por leis posteriores."]'::jsonb, '["ATUALIZAÇÃO: a composição do Contran foi reorganizada; confira o texto vigente.","É composto por Ministros de Estado."]'::jsonb, 'O Contran reúne representantes de várias pastas ministeriais.', '["Assertiva que compõe o Contran com representantes estaduais erra: é composto por Ministros de Estado."]'::jsonb, '[]'::jsonb, '["Art. 12"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-10' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'e7f9f4a45c763c075dd95dbece1a2a4457b1cc2b489f302e19c5eb23ed76f480'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Podem ser convidados a participar de reuniões do Contran, sem direito a voto, representantes de órgãos e entidades setoriais responsáveis ou impactados pelas propostas ou matérias em exame.', '["Convidados participam sem direito a voto."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior.","SEM direito a voto."]'::jsonb, 'Representante do setor de transporte participa da reunião, mas não vota.', '["Assertiva que concede voto aos convidados das reuniões do Contran erra."]'::jsonb, '[]'::jsonb, '["Art. 10"]'::jsonb, 'under_review', 'claude'
