insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Compete ao Contran estabelecer as normas regulamentares referidas no Código e as diretrizes da Política Nacional de Trânsito; coordenar os órgãos do Sistema; criar Câmaras Temáticas; estabelecer seu regimento interno e as diretrizes para o funcionamento dos Cetran e do Contrandife; estabelecer as diretrizes do regimento das JARI; entre outras competências de normatização, padronização da sinalização e formação de condutores.', '["Normas regulamentares e diretrizes da política.","Coordenação dos órgãos do sistema.","Câmaras Temáticas.","Diretrizes para Cetran e JARI."]'::jsonb, '["ATUALIZAÇÃO: o rol de competências foi alterado por leis posteriores; confira o texto vigente.","O Contran edita as resoluções."]'::jsonb, 'A resolução que padroniza a sinalização vem do Contran.', '["Assertiva que atribui ao Detran a edição das normas regulamentares do Código erra."]'::jsonb, '[]'::jsonb, '["Art. 7º"]'::jsonb, 'under_review', 'claude'
