insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Compete aos Cetran e ao Contrandife cumprir e fazer cumprir a legislação de trânsito, elaborar normas no âmbito de suas competências, responder a consultas, estimular e orientar campanhas educativas, julgar recursos nas hipóteses legais, e atuar como órgãos de coordenação, normatização e consulta em seus âmbitos, entre outras atribuições.', '["Normatização estadual e distrital.","Resposta a consultas.","Julgamento de recursos nas hipóteses legais.","Campanhas educativas."]'::jsonb, '["Suas normas valem no âmbito estadual ou distrital.","ATUALIZAÇÃO: o rol foi alterado por leis posteriores."]'::jsonb, 'O Cetran responde a consultas sobre a aplicação da legislação no estado.', '["Assertiva que atribui ao Cetran a edição de normas nacionais erra: suas normas valem no âmbito estadual."]'::jsonb, '[]'::jsonb, '["Art. 16"]'::jsonb, 'under_review', 'claude'
