insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Compete ao órgão máximo executivo de trânsito da União cumprir e fazer cumprir a legislação de trânsito e a execução das normas e diretrizes do Contran; supervisionar, coordenar e fiscalizar os órgãos delegados e a execução da Política Nacional de Trânsito; articular-se com os órgãos dos demais entes; entre outras atribuições relativas a registros, estatísticas e fiscalização.', '["Cumprir as normas do Contran.","Supervisão e correição dos órgãos delegados.","Articulação com os demais entes."]'::jsonb, '["Executa e supervisiona; não edita as normas regulamentares."]'::jsonb, 'O órgão federal supervisiona a execução da política nacional.', '["Assertiva que dá ao órgão máximo executivo da União a função normativa do Contran erra."]'::jsonb, '[]'::jsonb, '["Art. 12"]'::jsonb, 'under_review', 'claude'
