insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Compete às Polícias Militares dos Estados e do Distrito Federal executar a fiscalização de trânsito, quando e conforme convênio firmado, como agente do órgão ou entidade executivos de trânsito ou executivos rodoviários, concomitantemente com os demais agentes credenciados.', '["Fiscalização de trânsito pela Polícia Militar.","Depende de convênio.","Atua como agente do órgão de trânsito."]'::jsonb, '["Depende de CONVÊNIO com o órgão de trânsito ou rodoviário.","ATUALIZAÇÃO: outros incisos foram vetados ou revogados."]'::jsonb, 'A Polícia Militar fiscaliza o trânsito urbano por convênio com o órgão municipal.', '["Assertiva que dispensa convênio para a fiscalização de trânsito pela Polícia Militar erra."]'::jsonb, '[]'::jsonb, '["Art. 25"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-23' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '529ea75f22a2a69ce4cac1411e22e5a54f952228b30782da4c0335f3bd60ffcd'
