insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os órgãos e entidades executivos do Sistema Nacional de Trânsito podem celebrar convênio delegando as atividades previstas no Código, com vistas à maior eficiência e à segurança dos usuários da via. Podem ainda prestar serviços de capacitação técnica, assessoria e monitoramento das atividades relativas ao trânsito, por prazo estabelecido entre as partes, mediante ressarcimento dos custos.', '["Convênio de delegação de atividades.","Capacitação, assessoria e monitoramento.","Ressarcimento de custos."]'::jsonb, '["A delegação se faz por CONVÊNIO."]'::jsonb, 'O município delega ao estado parte da fiscalização por convênio.', '["Assertiva que permite a delegação de atividades sem convênio erra."]'::jsonb, '[]'::jsonb, '["Art. 23"]'::jsonb, 'under_review', 'claude'
