select u.id, u.content_sha256, 'Os agentes dos órgãos policiais da Câmara dos Deputados e do Senado Federal, mediante convênio com o órgão ou entidade de trânsito com circunscrição sobre a via, podem lavrar auto de infração de trânsito e remetê-lo ao órgão competente, nos casos de infração cometida nas dependências dessas Casas legislativas.', '["Polícias legislativas lavram auto de infração.","Depende de convênio com o órgão de trânsito."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior.","Depende de convênio."]'::jsonb, 'A polícia do Senado lavra auto de infração por convênio com o órgão de trânsito.', '["Assertiva que dá às polícias legislativas competência plena de trânsito sem convênio erra."]'::jsonb, '[]'::jsonb, '["Art. 25"]'::jsonb, 'under_review', 'claude'
