insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os usuários das vias terrestres devem abster-se de todo ato que possa constituir perigo ou obstáculo para o trânsito de veículos, pessoas ou animais, ou causar danos a propriedades públicas ou privadas, e abster-se de obstruir o trânsito ou torná-lo perigoso, atirando, depositando ou abandonando na via objetos ou substâncias, ou criando qualquer outro obstáculo.', '["Dever geral de não criar perigo ou obstáculo.","Vedado atirar ou abandonar objetos na via."]'::jsonb, '["Dever de TODOS os usuários, não só condutores."]'::jsonb, 'Deixar entulho no meio da via viola o dever de não criar obstáculo.', '["Assertiva que restringe o dever de não obstruir a via aos condutores erra: vale para todos os usuários."]'::jsonb, '[]'::jsonb, '["Art. 28"]'::jsonb, 'under_review', 'claude'
