insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O trânsito de veículos nas vias terrestres abertas à circulação obedece a normas como a circulação pelo lado direito da via, admitidas exceções sinalizadas; a distância de segurança lateral e frontal entre veículos; e regras de prioridade e preferência de passagem, inclusive dos veículos de emergência em serviço.', '["Circulação pela direita.","Distância de segurança.","Preferências de passagem."]'::jsonb, '["Rol extenso de normas gerais; consulte o texto integral dos incisos.","Veículos de emergência têm prioridade quando em serviço."]'::jsonb, 'O condutor mantém distância de segurança do veículo à frente.', '["Assertiva que permite circular pela esquerda como regra erra: a regra é a direita."]'::jsonb, '[]'::jsonb, '["Art. 30"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-29' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '038649320362b466307bd1fd13a6d327ae6b72aa999d9e15b472636ccbebf29a'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
