on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Todo condutor, ao perceber que outro que o segue tem o propósito de ultrapassá-lo, deve, se estiver na faixa da esquerda, deslocar-se para a faixa da direita, sem acelerar a marcha; e, se estiver nas demais faixas, manter-se naquela em que circula, sem acelerar. Os veículos mais lentos, quando em fila, devem manter distância suficiente entre si para permitir que os que os ultrapassem possam se intercalar na fila.', '["Quem é ultrapassado não acelera.","Faixa da esquerda: desloca-se para a direita.","Veículos lentos em fila mantêm distância."]'::jsonb, '["Quem é ultrapassado NÃO pode acelerar."]'::jsonb, 'O condutor na faixa da esquerda cede à direita ao perceber a ultrapassagem.', '["Assertiva que permite ao ultrapassado acelerar para impedir a manobra erra."]'::jsonb, '[]'::jsonb, '["Art. 32"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-30' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'd6b13adf9d9df5d9278f926e45c50f38ad84fd4b0a63192d8855f589efb72e30'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O condutor que tenha o propósito de ultrapassar um veículo de transporte coletivo parado, efetuando embarque ou desembarque de passageiros, deve reduzir a velocidade, dirigindo com atenção redobrada, ou parar o veículo, com vistas à segurança dos pedestres.', '["Reduzir a velocidade ou parar.","Atenção redobrada."]'::jsonb, '["Proteção do pedestre que embarca ou desembarca."]'::jsonb, 'Ao passar por um ônibus parado, o motorista reduz a velocidade.', '["Assertiva que permite ultrapassar o ônibus parado em velocidade normal erra."]'::jsonb, '[]'::jsonb, '["Art. 32"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-31' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '7a4e65c2e951e4ee92d9b877d8f9bcb0212b7d09ff4bd8940b0b1b46cf4c412d'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
