select u.id, u.content_sha256, 'Nas interseções e suas proximidades, o condutor não pode efetuar ultrapassagem, regra que busca evitar colisões no ponto de encontro das vias.', '["Proibida ultrapassagem em interseções e proximidades."]'::jsonb, '["Proibição absoluta no texto do artigo."]'::jsonb, 'Não se ultrapassa no cruzamento.', '["Assertiva que permite a ultrapassagem em interseção se a via estiver livre erra."]'::jsonb, '[]'::jsonb, '["Art. 32"]'::jsonb, 'under_review', 'claude'
