insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O condutor que queira executar uma manobra deve certificar-se de que pode executá-la sem perigo para os demais usuários da via que o seguem, precedem ou vão cruzar com ele, considerando sua posição, sua direção e sua velocidade.', '["Certificar-se de que a manobra é segura.","Considerar posição, direção e velocidade."]'::jsonb, '["Dever geral de cautela em manobras."]'::jsonb, 'Antes de mudar de faixa, o condutor confere o retrovisor.', '["Assertiva que dispensa a verificação dos que seguem o veículo erra."]'::jsonb, '[]'::jsonb, '["Art. 35"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-34' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '114ceac41075c58d6319f98c58d065d20a7e3b38fa7aeaacd234d75d129d7802'
