insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nas vias providas de acostamento, a conversão à esquerda e a operação de retorno devem ser feitas nos locais apropriados e, onde estes não existirem, o condutor deve aguardar no acostamento, à direita, para cruzar a pista com segurança.', '["Conversão e retorno em locais apropriados.","Na falta, aguardar no acostamento, à direita."]'::jsonb, '["Aguardar à DIREITA, no acostamento."]'::jsonb, 'Sem retorno sinalizado, o condutor aguarda no acostamento para cruzar.', '["Assertiva que manda aguardar no meio da pista para converter à esquerda erra."]'::jsonb, '[]'::jsonb, '["Art. 38"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-37' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'a5d823173b0985a0fc7fbb4138e3196b98af897b9e4622e5264cf7590a36007b'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
