insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nas vias urbanas, a operação de retorno deve ser feita nos locais para isso determinados, por meio de sinalização ou existência de locais apropriados, ou em outros locais que ofereçam condições de segurança e fluidez, observadas as características da via, do veículo, as condições meteorológicas e a movimentação de pedestres e ciclistas.', '["Retorno em locais determinados ou seguros.","Observância das condições da via e do ambiente."]'::jsonb, '["Retorno em local sem proibição e com segurança."]'::jsonb, 'O retorno é feito no local sinalizado.', '["Assertiva que permite retorno em qualquer ponto da via urbana erra."]'::jsonb, '[]'::jsonb, '["Art. 37"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-39' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'a3a92a8666e344bcf092cac6955e35e355255bcff0f17c96d28e0dfcbb3ef8e0'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
