insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O uso de luzes em veículo obedece a determinações como manter acesos os faróis, na luz baixa, à noite e, mesmo durante o dia, em túneis e sob chuva, neblina ou cerração; usar luz alta nas vias não iluminadas, exceto ao cruzar com outro veículo ou ao segui-lo; e não trocar de forma intermitente e por curto período a luz baixa e a alta, salvo para advertir ultrapassagem fora da área urbana.', '["Luz baixa à noite e em túneis, chuva e neblina.","Luz alta em vias não iluminadas, com exceções.","Regras sobre a troca intermitente."]'::jsonb, '["Luz baixa também de dia em túneis, chuva, neblina e cerração.","ATUALIZAÇÃO: regras sobre luzes diurnas em rodovias foram alteradas por lei posterior; confira o texto integral."]'::jsonb, 'Em túnel, mesmo de dia, mantém-se a luz baixa acesa.', '["Assertiva que dispensa os faróis acesos em túnel durante o dia erra."]'::jsonb, '[]'::jsonb, '["Art. 41"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-40' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '282c000f0ea1388ab3e4dc2c93914137ddab957b773cde3ac5876f7b56e2991b'
