insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nenhum condutor deve frear bruscamente seu veículo, salvo por razões de segurança.', '["Frenagem brusca só por segurança."]'::jsonb, '["Exceção: razões de segurança."]'::jsonb, 'A frenagem brusca para evitar atropelamento é permitida.', '["Assertiva que proíbe frenagem brusca em qualquer hipótese erra."]'::jsonb, '[]'::jsonb, '["Art. 43"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-42' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'e7a034aa5f10c733d119d383a8253c5ff80ced80cf4006a3753bc34b765585ba'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
