on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Ao aproximar-se de qualquer tipo de cruzamento, o condutor do veículo deve demonstrar prudência especial, transitando em velocidade moderada, de forma que possa deter seu veículo com segurança para dar passagem a pedestre e a veículos que tenham o direito de preferência.', '["Prudência especial nos cruzamentos.","Velocidade moderada.","Dar passagem a quem tem preferência."]'::jsonb, '["Vale para qualquer cruzamento."]'::jsonb, 'Ao chegar ao cruzamento, o condutor reduz para poder parar.', '["Assertiva que dispensa prudência especial em cruzamentos sinalizados erra."]'::jsonb, '[]'::jsonb, '["Art. 45"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-44' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '8f8b122f5fb7916c759158068caa79799219baebd3f5111c64a13d8470a59e6a'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
