insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Sempre que for necessária a imobilização temporária de um veículo no leito viário, em situação de emergência, deve ser providenciada a imediata sinalização de advertência, na forma estabelecida pelo Contran.', '["Sinalização imediata em imobilização de emergência.","Forma definida pelo Contran."]'::jsonb, '["Sinalização na forma do Contran, como o triângulo."]'::jsonb, 'Em pane na pista, o condutor coloca o triângulo de sinalização.', '["Assertiva que dispensa a sinalização na imobilização por emergência erra."]'::jsonb, '[]'::jsonb, '["Art. 47"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-46' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '04fdd82de6e1778c31e858be795e41b6657ff5c13ab8e85c07b554b083ef6074'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
