insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As vias abertas à circulação classificam-se, de acordo com sua utilização, em vias urbanas, que podem ser de trânsito rápido, arteriais, coletoras ou locais, e vias rurais, que são as rodovias e as estradas.', '["Vias urbanas: trânsito rápido, arterial, coletora e local.","Vias rurais: rodovias e estradas."]'::jsonb, '["Quatro tipos de vias urbanas e dois de vias rurais."]'::jsonb, 'A avenida de ligação entre bairros é via arterial.', '["Assertiva que inclui a via rápida como via rural erra."]'::jsonb, '[]'::jsonb, '["Art. 61"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-60' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'ff7c889b71d42a57924f1d5795da370e715b9419e2222eacca0920d7dbbb06ff'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
