insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A velocidade máxima permitida para a via é indicada por sinalização. Onde não houver sinalização regulamentadora, é de oitenta quilômetros por hora nas vias de trânsito rápido, sessenta nas arteriais, quarenta nas coletoras e trinta nas locais. Nas vias rurais: em rodovias de pista dupla, 110 km/h para automóveis, camionetas, caminhonetes e motocicletas e 90 km/h para os demais veículos; em rodovias de pista simples, 100 km/h para automóveis, camionetas, caminhonetes e motocicletas e 90 km/h para os demais; e nas estradas, 60 km/h. O órgão com circunscrição pode regulamentar, por sinalização, velocidades superiores ou inferiores.', '["Urbanas: oitenta, sessenta, quarenta e trinta quilômetros por hora.","Rodovias de pista dupla: 110 km/h e 90 km/h.","Rodovias de pista simples: 100 km/h e 90 km/h.","Estradas: 60 km/h.","Regulamentação por sinalização prevalece."]'::jsonb, '["ATUALIZAÇÃO: os limites das rodovias foram alterados por lei posterior.","Esses valores valem onde NÃO houver sinalização regulamentadora."]'::jsonb, 'Na via local sem placa, o limite é de trinta quilômetros por hora.', '["Assertiva que fixa em sessenta quilômetros por hora o limite das vias locais sem sinalização erra: são trinta."]'::jsonb, '[]'::jsonb, '["Art. 218"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-61' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'a558443b3c1821a8131950562baeea36c90277f7f52bcd43be56c1d2460e5ad5'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
