insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A velocidade mínima não pode ser inferior à metade da velocidade máxima estabelecida, respeitadas as condições operacionais de trânsito e da via.', '["Mínimo: metade da velocidade máxima.","Respeitadas as condições operacionais."]'::jsonb, '["Metade da máxima, não um valor fixo."]'::jsonb, 'Na via com limite de oitenta, a mínima é quarenta, salvo condições operacionais.', '["Assertiva que fixa a velocidade mínima em um terço da máxima erra: é a metade."]'::jsonb, '[]'::jsonb, '["Art. 61"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-62' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '6f804be9cf1d97aac1311fe65073b42cba3afba9cf3a6250dde7c0801a60e271'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
