on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As crianças com idade inferior a dez anos que não tenham atingido 1,45 m de altura devem ser transportadas nos bancos traseiros, em dispositivo de retenção adequado para cada idade, peso e altura, salvo exceções relacionadas a tipos específicos de veículos regulamentadas pelo Contran. O Contran disciplina o uso excepcional de dispositivos de retenção no banco dianteiro e suas especificações técnicas.', '["Menores de dez anos que não tenham atingido 1,45 m.","Banco traseiro.","Dispositivo de retenção adequado.","Exceções regulamentadas pelo Contran."]'::jsonb, '["ATUALIZAÇÃO: a regra de idade e altura veio de lei posterior.","O requisito é idade menor que dez anos E altura menor que 1,45 m."]'::jsonb, 'A criança de oito anos com 1,30 m viaja no banco traseiro com dispositivo de retenção.', '["Assertiva que dispensa o dispositivo de retenção para criança de sete anos erra."]'::jsonb, '[]'::jsonb, '["Art. 168"]'::jsonb, 'under_review', 'claude'
