insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É obrigatório o uso do cinto de segurança para condutor e passageiros em todas as vias do território nacional, salvo em situações regulamentadas pelo Contran.', '["Cinto obrigatório para condutor e passageiros.","Em todas as vias do país.","Exceções regulamentadas pelo Contran."]'::jsonb, '["Vale para condutor E passageiros, em TODAS as vias."]'::jsonb, 'O passageiro do banco traseiro também usa cinto.', '["Assertiva que dispensa o cinto dos passageiros do banco traseiro erra."]'::jsonb, '[]'::jsonb, '["Art. 167"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-65' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '60952e7f297324306d5e68cc1f4285b4ba7e41b29f2c71bd903bba5889fd61aa'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
